UPDATE user_mobile_change_face_verification
SET otp_token = #{otpToken}
WHERE face_verify_token = #{faceVerifyToken}
  AND status = 'VERIFIED_PENDING'

UPDATE user_mobile_change_face_verification
SET status = 'PROMOTED',
    promoted_at = #{promotedAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE face_verify_token = #{faceVerifyToken}
  AND status = 'VERIFIED_PENDING'
